@startuml

class Faculty {
  + Name : string
}

class Institute {
  + Name : string
  + Address : string
}

class Employee {
  + SocialSecurityNumber : string
  + Name : string
  + Email : string
}

class ResearchAssistant extends Employee {
  + FieldOfResearch : string
}

class AdministrativeStaff extends Employee {}

class Lecturer extends ResearchAssistant {}

class Course {
  + ID : int
  + Name : string
  + WeeklyDuration : int
}

class ProjectInvolvement {
  + ProjectName : string
  + StartDate : date
  + EndDate : date
  + Hours : int
}

Faculty "1" -- "*" Institute
Faculty "1" -- "1" Employee : headed by
Institute "1" -- "*" ResearchAssistant : has
ResearchAssistant "1" -- "*" ProjectInvolvement
ResearchAssistant "1" -- "*" Course : teaches

@enduml

